function createCatalogV13(){return BASE_CATALOG_V13.map(s=>({...s,moodIds:[...s.moodIds]}));}
function upgradeCatalogV13(target){
 if(!target.settings||typeof target.settings!=='object')target.settings={theme:'carbono'};
 if(Number(target.settings.baseCatalogVersion)>=13)return false;
 // Never touch records: they have independent strategy text snapshots.
 const v12=new Map(BASE_CATALOG_V12.map(x=>[x.id,x]));
 for(const s of target.strategies){
  const old=v12.get(s.id);
  if(!old||s.retiredByCatalog)continue;
  const unchanged=s.createdAt===old.createdAt&&s.activityId===old.activityId&&s.text===old.text&&s.kind===old.kind&&
   (s.timing||'agora')===old.timing&&s.active===true&&!s.updatedAt&&Array.isArray(s.moodIds)&&
   JSON.stringify([...s.moodIds].sort())===JSON.stringify([...old.moodIds].sort());
  if(unchanged){s.active=false;s.retiredByCatalog=13;}
 }
 const ids=new Set(target.strategies.map(s=>s.id));
 for(const entry of createCatalogV13())if(!ids.has(entry.id))target.strategies.push(entry);
 // Keep the six original sleep moods, and add the three from the approved Goggins matrix.
 if(!Array.isArray(target.moods.sleep))target.moods.sleep=[];
 for(const name of ['Cansado','Desmotivado','Disposto']){
  const id='m_'+name.toLowerCase();
  if(!target.moods.sleep.some(m=>m.id===id))target.moods.sleep.push({id,name,icon:MOOD_ICONS[name]||'circle',active:true});
 }
 if(!Array.isArray(target.briefings))target.briefings=[];
 target.settings.baseCatalogVersion=13;
 return true;
}
function seedData(){
  const moods={};
  Object.entries(MOOD_NAMES).forEach(([aid,names])=>{moods[aid]=names.map(n=>({id:'m_'+n.toLowerCase().replace(/\s+/g,'_'),name:n,icon:MOOD_ICONS[n]||'circle',active:true}));});
  return {schemaVersion:2,moods,strategies:createCatalogV13(),records:[],briefings:[],settings:{theme:'carbono',baseCatalogVersion:13},createdAt:new Date().toISOString()};
}

