function render(){const contextual=rec();document.body.dataset.activity=contextual&&!['home','history','retro'].includes(ui.view)?contextual.activityId:'';main.classList.toggle('is-home',ui.view==='home');main.classList.toggle('has-strategy-dock',ui.view==='strategies');const routes={home:renderHome,quick:renderQuick,moods:renderMoods,'mood-manager':renderMoodManager,strategies:renderStrategies,'strategy-manager':renderStrategyManager,execute:renderExecute,feedback:renderFeedback,history:renderHistory,record:renderRecord,'record-edit':renderRecord,retro:renderRetro,briefing:renderBriefing};main.innerHTML=(routes[ui.view]||renderHome)();renderTabs();}
function updateMoods(field,id){const r=rec();if(!r)return;const catalog=activityMoods(r.activityId,false).find(m=>m.id===id);if(!catalog)return;const current=r[field]||[];r[field]=current.some(m=>m.id===id)?current.filter(m=>m.id!==id):[...current,{id:catalog.id,name:catalog.name}];touch(r);render();}
function createFile(kind){const payload=kind==='historico'?{type:'historico',schemaVersion:2,exportedAt:new Date().toISOString(),records:db.records}:{type:'backup',schemaVersion:2,exportedAt:new Date().toISOString(),data:db};const filename=`${kind==='historico'?'historico':'backup'}-rituais-${nowLocal().date}.json`;const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.download=filename;a.href=url;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Arquivo preparado para download.');}
function mergeMoodName(name,activity){return activityMoods(activity,false).some(m=>nameKey(m.name)===nameKey(name));}
function saveMood(form){const r=rec();if(!r)return;const id=form.dataset.id;const n=String(new FormData(form).get('name')||'').trim();if(!n)return;const match=activityMoods(r.activityId,false).some(m=>m.id!==id&&nameKey(m.name)===nameKey(n));if(match){toast('Já existe um mood com esse nome.');return;}if(id){const m=activityMoods(r.activityId,false).find(x=>x.id===id);if(!m)return;m.name=n;}else{const m={id:uid(),name:n,icon:MOOD_ICONS[n]||'circle',active:true};db.moods[r.activityId].push(m);if(ui.view==='moods')r.initialMoods.push({id:m.id,name:m.name});}persist();ui.addMood=false;ui.editMoodId=null;render();}
function saveStrategy(form){const r=rec();if(!r)return;const data=new FormData(form);const text=String(data.get('text')||'').trim();const moodIds=data.getAll('for-mood').map(String);if(!text){toast('Digite o texto da estratégia.');return;}const editingId=form.dataset.id;const inManager=form.dataset.manager==='1';if(!moodIds.length){toast('Selecione pelo menos um mood.');return;}const kind=data.has('is-phrase')?'frase':'acao';const timing=data.get('timing')==='antes'?'antes':'agora';if(editingId){const s=db.strategies.find(s=>s.id===editingId);if(!s)return;s.text=text;s.moodIds=moodIds;s.kind=kind;s.timing=timing;s.updatedAt=new Date().toISOString();}else if(inManager||data.has('permanent')){const s={id:uid(),activityId:r.activityId,moodIds,text,kind,timing,active:true,createdAt:new Date().toISOString()};db.strategies.push(s);}else{r.temporaryStrategies.push({id:uid(),activityId:r.activityId,moodIds,text,kind,timing});touch(r);}persist();ui.addingStrategy=false;ui.editStrategyId=null;render();}
function savePreparation(){const r=rec();if(!r)return;const prev=r.strategies||[];r.strategies=candidates(r).map(s=>{const old=prev.find(p=>p.sourceId===s.sourceId||nameKey(p.text)===nameKey(s.text));return old?{...old}: {id:uid(),sourceId:s.sourceId,text:s.text,kind:s.kind||'acao',timing:s.timing||'agora',done:false,helped:null};});r.preparationSaved=true;touch(r);view('execute');}
function toggleStatus(r,status){r.status=status;touch(r);ui.historyYear=Number(r.date.slice(0,4));ui.historyMonth=Number(r.date.slice(5,7))-1;ui.historyDay=Number(r.date.slice(8,10));ui.recordId=null;view('history');}
function confirmPermanent(id){const s=db.strategies.find(x=>x.id===id);if(!s)return;if(s.active){if(!window.confirm('Excluir esta estratégia do repertório futuro? Os registros antigos serão preservados.'))return;s.active=false;}else{s.active=true;}persist();render();}
function setMonth(delta){const d=new Date(ui.historyYear,ui.historyMonth+delta,1);ui.historyYear=d.getFullYear();ui.historyMonth=d.getMonth();ui.historyDay=null;render();}
function fromRecordToHistory(){ui.recordId=null;ui.addingStrategy=false;view('history');}
function openRecord(id){ui.recordId=id;ui.feedbackExpanded=false;ui.addingStrategy=false;view('record');}
function exportWarning(){return storageFault?'Os dados deste navegador talvez não estejam sendo salvos corretamente. Faça backup antes de continuar.':'';}
// Exclusão afeta somente este registro; nunca o repertório permanente.
function deleteCurrentRecord(){
 const r=rec();if(!r)return;
 const a=ACT(r.activityId);
 if(!window.confirm(`Excluir definitivamente o registro de ${a.name} de ${shortDate(r.date)}${r.time?' às '+r.time:''}? Esta ação não poderá ser desfeita.`))return;
 const previous=db.records;
 db.records=db.records.filter(x=>x.id!==r.id);
 for(const b of db.briefings||[])for(const sec of Object.values(b.activities||{}))if(sec.recordId===r.id)sec.recordId=null;
 if(!persist()){db.records=previous;return;}
 window.RituaisPush?.queueSync?.(briefPushSnapshot());
 ui.historyYear=Number(r.date.slice(0,4));ui.historyMonth=Number(r.date.slice(5,7))-1;ui.historyDay=Number(r.date.slice(8,10));
 ui.recordId=null;view('history');toast('Registro excluído.');
}
// Histórico exportado: acrescenta somente registros novos, sem tocar nas estratégias pessoais.
function normalizeImportedRecord(r){
 if(!r||typeof r!=='object'||Array.isArray(r))throw Error('O histórico contém um registro inválido.');
 if(typeof r.id!=='string'||!r.id.trim()||r.id.length>240)throw Error('O histórico contém um registro sem identificador válido.');
 if(!ACTIVITIES.some(a=>a.id===r.activityId))throw Error('O histórico contém uma atividade desconhecida.');
 if(typeof r.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date+'T12:00:00').getDate()!==Number(r.date.slice(8)))throw Error('O histórico contém uma data inválida.');
 if(typeof r.time!=='string'||(r.time!==''&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(r.time)))throw Error('O histórico contém um horário inválido.');
 if(!['andamento','finalizado'].includes(r.status))throw Error('O histórico contém um status desconhecido.');
 const string=(v,max=400)=>typeof v==='string'?v.slice(0,max):'';
 const moods=v=>{if(!Array.isArray(v)||v.length>100)throw Error('O histórico contém moods inválidos.');return v.map(m=>{if(!m||typeof m!=='object')throw Error('O histórico contém um mood inválido.');return {id:string(m.id,240),name:string(m.name,100)};});};
 const arrStrings=v=>{if(!Array.isArray(v)||v.length>500)throw Error('O histórico contém estratégias inválidas.');return v.filter(x=>typeof x==='string').map(x=>x.slice(0,240));};
 const strategies=v=>{if(!Array.isArray(v)||v.length>500)throw Error('O histórico contém estratégias inválidas.');return v.map(s=>{if(!s||typeof s!=='object'||typeof s.text!=='string')throw Error('O histórico contém uma estratégia inválida.');return {id:string(s.id,240)||uid(),sourceId:string(s.sourceId,240),text:s.text.slice(0,3000),kind:s.kind==='frase'?'frase':'acao',timing:s.timing==='antes'?'antes':'agora',done:s.done===true,helped:typeof s.helped==='boolean'?s.helped:s.helped==='incerto'?'incerto':null};});};
 if(typeof r.notes!=='string'||r.notes.length>50000)throw Error('O histórico contém observações inválidas.');
 return {id:r.id,activityId:r.activityId,date:r.date,time:r.time,createdAt:string(r.createdAt,100)||new Date().toISOString(),updatedAt:string(r.updatedAt,100)||new Date().toISOString(),status:r.status,initialMoods:moods(r.initialMoods),duringMoods:moods(r.duringMoods),finalMoods:moods(r.finalMoods),excludedStrategyIds:arrStrings(r.excludedStrategyIds),preventionSelectedIds:arrStrings(r.preventionSelectedIds||[]),temporaryStrategies:(()=>{if(!Array.isArray(r.temporaryStrategies)||r.temporaryStrategies.length>500)throw Error('O histórico contém estratégias temporárias inválidas.');return r.temporaryStrategies.map(s=>({id:string(s?.id,240)||uid(),activityId:r.activityId,moodIds:arrStrings(s?.moodIds),text:string(s?.text,3000),kind:s?.kind==='frase'?'frase':'acao',timing:s?.timing==='antes'?'antes':'agora'}));})(),strategies:strategies(r.strategies),entryMode:r.entryMode==='registro'?'registro':'preparacao',preparationSaved:r.preparationSaved===true,result:['sim','nao'].includes(r.result)?r.result:null,durationMinutes:Number.isInteger(r.durationMinutes)&&r.durationMinutes>=0&&r.durationMinutes<=9999?r.durationMinutes:null,notes:r.notes.slice(0,3000)};
}
async function importHistory(file){
 if(file.size>12*1024*1024)throw Error('O arquivo supera 12 MB. Divida o histórico antes de importar.');
 let payload;try{payload=JSON.parse(await file.text());}catch(e){throw Error('O arquivo não contém JSON válido.');}
 if(!payload||payload.type!=='historico'||payload.schemaVersion!==2||!Array.isArray(payload.records))throw Error('Selecione um arquivo de Exportar Histórico (JSON), não um backup completo.');
 if(payload.records.length>15000)throw Error('O histórico contém registros demais para uma única importação.');
 const imported=payload.records.map(normalizeImportedRecord); // valida tudo antes de modificar os dados
 const ids=new Set(db.records.map(r=>r.id));
 const pending=[];let duplicates=0;
 for(const r of imported){if(ids.has(r.id)){duplicates++;continue;}ids.add(r.id);pending.push(r);}
 if(!pending.length){toast(duplicates?'Todos os registros deste arquivo já estão no aplicativo.':'O arquivo não contém registros.');return;}
 if(!window.confirm(`Importar ${pending.length} novo(s) registro(s)? ${duplicates?duplicates+' já existente(s) serão ignorados. ':''}Os registros atuais e as personalizações serão preservados.`))return;
 const previous=db.records;db.records=[...previous,...pending];
 if(!persist()){db.records=previous;throw Error('Não foi possível salvar o histórico importado.');}
 ui.recordId=null;setTab('history');
 const latest=pending.reduce((a,b)=>a.date>=b.date?a:b);
 ui.historyYear=Number(latest.date.slice(0,4));ui.historyMonth=Number(latest.date.slice(5,7))-1;ui.historyDay=Number(latest.date.slice(8,10));
 render();
 toast(`${pending.length} registro(s) importado(s)${duplicates?' · '+duplicates+' repetido(s) ignorado(s)':''}.`);
}
