 'edit-permanent':el=>{ui.editStrategyId=ui.editStrategyId===el.dataset.id?null:el.dataset.id;ui.addingStrategy=false;render();},
 'toggle-permanent':el=>confirmPermanent(el.dataset.id),
 'cancel-edit':()=>{ui.addMood=false;ui.addingStrategy=false;ui.editMoodId=null;ui.editStrategyId=null;render();},
 'result':el=>{const r=rec();r.result=r.result===el.dataset.value?null:el.dataset.value;touch(r);render();},
 'duration':el=>{const r=rec();const n=Number(el.dataset.value);r.durationMinutes=r.durationMinutes===n?null:n;touch(r);render();},
 'toggle-during-mood':el=>updateMoods('duringMoods',el.dataset.id),
 'toggle-final-mood':el=>updateMoods('finalMoods',el.dataset.id),
